def main() -> None:
    data = json.loads(COLLOC_PATH.read_text(encoding="utf-8"))
    existing_ids = {d["id"] for d in data}
    reserved = load_reserved_terms(exclude_file=None)
    added = 0

    for spec in NEW_COLLOCATION_DECKS:
        if spec["id"] in existing_ids:
            continue
        cards = []
        for row in spec["cards"]:
            term, anchor, meaning, syns, ants, s1, t1, s2, t2 = row
            low = term.strip().lower()
            if low in reserved:
                continue
            assert contains_exact_term(s1, term), f"s1 missing {term}: {s1}"
            assert contains_exact_term(s2, term), f"s2 missing {term}: {s2}"
            reserved.add(low)
            cards.append({
                "anchor": anchor,
                "term": term,
                "meaning": meaning,
                "synonyms": syns,
                "antonyms": ants,
                "sentence": s1,
                "translation": t1,
                "extraExamples": [{"sentence": s2, "translation": t2}],
            })
            added += 1
        data.append({
            "id": spec["id"],
            "level": spec["level"],
            "title": spec["title"],
            "cards": cards,
        })

    COLLOC_PATH.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    total = sum(len(d["cards"]) for d in data)
    print(f"Collocations updated: {len(data)} decks, added {added}, total {total}")


if __name__ == "__main__":
    main()
